import { lazy } from 'react';
import { BookOpen as IcBookOpen, CalendarDays as IcCalendarDays, FileText as IcFileText } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Enablement — hub page for the Sales menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'SalesEnablement'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const SalesPlaybooks = lazy(() => import('./SalesPlaybooks'));
const SalesCalendar = lazy(() => import('./SalesCalendar'));
const SalesDocuments = lazy(() => import('./SalesDocuments'));

export const TABS = [
  { id: 'playbooks', label: 'Playbooks', icon: IcBookOpen, page: 'SalesPlaybooks', Component: SalesPlaybooks },
  { id: 'calendar', label: 'Calendar', icon: IcCalendarDays, page: 'SalesCalendar', Component: SalesCalendar },
  { id: 'documents', label: 'Documents', icon: IcFileText, page: 'SalesDocuments', Component: SalesDocuments },
];

export default function SalesEnablement({ setPage }) {
  return (
    <TabHub
      icon={IcBookOpen}
      eyebrow="Sales"
      title="Enablement"
      subtitle="Playbooks, the sales calendar and the document library"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
